pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint seed) public {
        // Capture pot before play
        uint potBefore = c.pot();
        uint playVal = 10; // TICKET_AMOUNT
        // Use seed to influence random outcome:
        // If seed % 2 == 0, we expect random == 0 (win) at some point.
        // But we cannot control random; we can only observe the outcome.
        // We'll fuzz by sending different amounts of ether to affect block.difficulty? No, just fuzz seed for different random outcomes.
        // Instead, we can call play multiple times until win occurs, or we can assert the rule for every play.
        // A simpler approach: drive a call to play and check the invariant.
        // The invariant: when random == 0, pot after should equal (potBefore + 10 - 1) = potBefore + 9.
        // Since we don't know random, we can wrap in try/catch to get the pot after and check conditionally.
        // But better: replay the same call twice? No.
        // Alternative: call play, then check that pot satisfies one of two possible outcomes.
        vm.deal(address(this), 10 ether);
        c.play{value: playVal}();
        uint potAfter = c.pot();
        // The rule: potAfter must be either 0 (if random == 1) or potBefore + 9 (if random == 0).
        assertTrue(potAfter == 0 || potAfter == potBefore + 9);
    }
}

