pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        // Bound seed to avoid extremely large values
        seed = bound(seed, 0, 100);

        // Record pot before play
        uint256 potBefore = c.pot();

        // Simulate a losing play by setting the block randomness such that random != 0
        // We use vm.warp and vm.difficulty to control keccak256 output
        // For a losing play, random must be 1; we want to ensure the call doesn't revert
        vm.deal(address(c), 0); // ensure c has no balance
        vm.deal(address(this), 10); // give this contract 10 wei

        // Since we cannot directly control random, we assume the fuzzer will eventually hit a losing case
        // Instead, we call play() and check the rule after the call
        // We assume the function does not revert (it will revert if msg.value != 10)
        c.play{value: 10}();

        uint256 potAfter = c.pot();

        // The rule: if the call did not revert, then potAfter >= potBefore + 10
        // This always holds in C because pot increases by 10 regardless of random outcome
        // In M, pot is reset to 0 before the random check, so potAfter could be less
        assertTrue(potAfter >= potBefore + 10);
    }
}

