contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed, uint256 callerSeed) public {
        vm.assume(seed < 1000000);
        vm.assume(callerSeed < 1000000);

        // Simulate a win scenario: seed % 2 == 0 leads to random == 0
        vm.warp(seed);
        vm.difficulty(seed);
        address player = vm.addr(callerSeed);

        uint256 playerBalanceBefore = player.balance;
        uint256 bankBalanceBefore = address(c.bank()).balance;

        vm.deal(player, 10 ether);
        vm.prank(player);
        c.play{value: 10 wei}();

        uint256 playerBalanceAfter = player.balance;
        uint256 bankBalanceAfter = address(c.bank()).balance;

        // The rule: after a win, the player receives pot - 1, where pot was just increased by msg.value
        // In C, pot before deduction = 10 (since msg.value = 10)
        // If random == 0, player gets pot - 1 = 9
        // If random != 0, nothing changes
        // But we can't read random directly, so we check that if player balance increased, it increased by exactly 9 or 10
        assertTrue(
            (playerBalanceAfter - playerBalanceBefore == 0) || 
            (playerBalanceAfter - playerBalanceBefore == 9) ||
            (playerBalanceAfter - playerBalanceBefore == 10)
        );
        // Additional constraint: bank balance must change by at most 1 (transfer) or none
        assertTrue(
            (bankBalanceAfter - bankBalanceBefore == 0) || 
            (bankBalanceAfter - bankBalanceBefore == 1)
        );
    }
}

