import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        address player = makeAddr("player");
        vm.deal(player, 10 ether);

        // Get bank address
        address bank = c.bank();

        // Record bank balance before
        uint256 bankBefore = bank.balance;

        // Play with a random seed that determines win/loss
        // We'll use vm.assume to ensure random == 0 (player wins)
        // We need to force the random outcome to be 0 by setting block.timestamp and block.difficulty
        // Since random = keccak256(block.timestamp, block.difficulty, msg.sender) % 2
        // We can just try both and capture the winning case via vm.assume

