        uint256 diff = seed + 1;
        vm.warp(ts);
        vm.difficulty(diff);

        // Compute what random will be
        uint256 expectedRandom = uint256(keccak256(abi.encodePacked(ts, diff, player))) % 2;
        vm.assume(expectedRandom == 0);

        c.play{value: 10 ether}();

        // After play, bank should have received the fee
        uint256 bankAfter = bank.balance;
        assertTrue(bankAfter == bankBefore + 1 ether);
    }
