        vm.deal(address(this), amount);
        // Play once with the given amount
        c.play{value: amount}();
        // After the call, if someone wins (random == 0), pot must be 0
        // We cannot know random, but the invariant is: if the player lost, pot may be >0; if won, pot must be 0.
